const FLIP = new Set(['undo', 'chevron', 'back', 'logout', 'message']);

function icon(name, cls = '') {
  const flip = FLIP.has(name) ? ' flip-rtl' : '';
  return `<svg class="ic ${cls}${flip}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${ICONS[name] || ''}</svg>`;
}

/* The Corniche mark: a shop awning (blue and white, scalloped) over a "C"
   that doubles as the curve of the bay, with the sun in sand. */
function brandMark(size = 36) {
  return `<svg class="mark" width="${size}" height="${size}" viewBox="0 0 48 48" aria-hidden="true">
    <rect width="48" height="48" rx="12" fill="#0b5266"/>
    <g clip-path="url(#awn)">
      <path d="M6 10h36v8H6z" fill="#fff"/>
      <path d="M6 10h6v8H6zM18 10h6v8h-6zM30 10h6v8h-6z" fill="#e3f0f3"/>
    </g>
    <path d="M6 18a3 3 0 0 0 6 0a3 3 0 0 0 6 0a3 3 0 0 0 6 0a3 3 0 0 0 6 0a3 3 0 0 0 6 0a3 3 0 0 0 6 0" fill="#fff"/>
    <circle cx="33" cy="31" r="4" fill="#e9a93a"/>
    <path d="M27 26.5a9 9 0 1 0 0 11" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round"/>
    <defs><clipPath id="awn"><rect x="6" y="10" width="36" height="9" rx="2"/></clipPath></defs>
  </svg>`;
}
